use vstd::prelude::*;
verus! {
spec fn triangle(n: nat) -> nat
    decreases n,
{
    if n == 0 { 0 } else { n + triangle((n - 1) as nat) }
}

proof fn triangle_is_monotonic(i: nat, j: nat)
    ensures i <= j ==> triangle(i) <= triangle(j),
    decreases j,
{
    if j > 0 { triangle_is_monotonic(i, (j - 1) as nat); }
}
// fn loop_triangle(...) as traced below
fn main() {}
}

fn loop_triangle(n: u32) -> (sum: u32)
    requires triangle(n as nat) <= u32::MAX,
    ensures sum == triangle(n as nat),
{
    let mut sum: u32 = 0;
    let mut idx: u32 = 0;
    while idx < n
        invariant
            idx <= n,
            sum == triangle(idx as nat),
            triangle(n as nat) <= u32::MAX,
        decreases n - idx,
    {
        idx = idx + 1;
        assert(sum + idx <= u32::MAX) by {
            triangle_is_monotonic(idx as nat, n as nat);
        }
        sum = sum + idx;
    }
    sum
}

use vstd::prelude::*;
use vstd::simple_pptr::*;
verus! {
fn main() {
    let (p, Tracked(perm)) = PPtr::<u64>::new(5);
    let x = p.read(Tracked(&perm));
    assert(x == 5);
    let y = p.into_inner(Tracked(perm)); // frees the cell
    let z = p.read(Tracked(&perm));      // use after free
}
}

